import { anyApi } from "convex/server";
import type { FunctionReference } from "convex/server";
import type { Timeline } from "../../convex/queue";

/**
 * `convex/queue.ts` exists on disk and is frozen against its own validators,
 * but `convex/_generated/api.d.ts` (a build artifact regenerated by
 * `npx convex dev`/`convex codegen`, both of which talk to the deployment)
 * does not list the `queue` module yet. Same `anyApi` workaround `src/
 * library/summaryApi.tsx` and `src/library/limitsApi.tsx` already use for
 * `convex/summary.ts`/`convex/limits.ts` — this resolves to the exact same
 * function reference at runtime. Swap for `api.queue.timeline` once codegen
 * has run and picked up the module.
 */
// `now` is REQUIRED (convex/queue.ts's own validator: a query must never
// read the wall clock itself — convex/_generated/ai/guidelines.md "Do not
// read the wall clock inside a query"). Callers refresh it the same way
// src/library/Library.tsx refreshes `now` for `summaryQuery`/`healthQuery`.
// SAFETY: `anyApi.queue.timeline` is typed as `FunctionReference<any, any>`
// because `convex/_generated/api.d.ts` has not picked up `convex/queue.ts`
// yet (see the module comment above); the `any` type parameters make this a
// single, non-widening assertion to the reference's real, frozen contract.
export const queueTimelineQuery = anyApi.queue.timeline as FunctionReference<
  "query",
  "public",
  { now: number },
  Timeline
>;
